import { localizedPrice, type PriceSearchParams } from "@/lib/localized-price";
import { requireUser } from "@/lib/session";
import { BillingControls } from "@/components/billing-controls";
export const metadata = {
  title: "Checkout confirmation",
  robots: { index: false, follow: false },
};
export default async function UsageReturn({
  searchParams,
}: {
  searchParams: PriceSearchParams;
}) {
  await requireUser();
  const price = await localizedPrice(searchParams);
  // Redirect parameters are untrusted and deliberately never consumed.
  return (
    <main
      id="main-content"
      tabIndex={-1}
      className="min-h-dvh bg-[var(--confirmation-bg)] px-4 py-8 text-[var(--confirmation-text)] [font-family:Arial,Helvetica,sans-serif] sm:px-6 sm:pt-16 sm:pb-24"
    >
      <div className="mx-auto max-w-[1222px]">
        <div className="max-w-[1142px]">
          <div className="mb-[30px] flex min-h-[52px] items-center">
            <h1 className="text-[22px] font-medium leading-7 tracking-normal text-[var(--confirmation-muted)] [font-family:inherit]">
              Checkout confirmation
            </h1>
          </div>
          <BillingControls returning advertisedPrice={price} />
        </div>
      </div>
    </main>
  );
}
